actions.script:
def zinr = context.zinr
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = ec.l10n.parseTimestamp(fromD + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
def de = ec.l10n.parseTimestamp(thruD + ' 23:59:59.999', 'yyyy-MM-dd HH:mm:ss.SSS')
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
periodStr = fromD + ' to ' + thruD
def paymentReport=ec.service.sync().name('zenith.pos.PosServices.get#PosPaymentBreakdown').parameters([fromDate:ds,thruDate:de]).call()
def methodMap=[:]
(paymentReport.rows ?: []).each { m -> methodMap[m.paymentMethod]=[m:m.paymentMethod,amt:m.totalAmount,cnt:m.transactionCount] }
def total=paymentReport.totalAmount ?: BigDecimal.ZERO
def all = methodMap.values().sort { -(it.amt as BigDecimal) }
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) all = all.findAll { (it.m ?: '').toLowerCase().contains(stx) }
def num = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
rows = all.collect { r ->
    def pct = total > 0 ? (r.amt * 100 / total) : 0.0G
    [m:x(r.m), amt:num(r.amt), cnt:r.cnt.toString(), pct:ec.l10n.format(pct, '#0.00') + '%'] }
totalStr = num(total)
rowCountStr = all.size().toString()
